from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [[background] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if (r1 - r0 + 1) * (c1 - c0 + 1) >= 4:
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
    return out
